// Converts NotTennaPod-iOS's Localizable.strings (Android AntennaPod 3.12.1's
// English strings) into src/generated/strings.ts, so the browser's wording is
// the app's and is never retyped. With --check, fails if the generated file is
// out of date with the iOS source.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = process.env.NTP_IOS_STRINGS ?? join(root, "..", "NotTennaPod-iOS", "App", "Resources", "en.lproj", "Localizable.strings");
const plurals = process.env.NTP_IOS_PLURALS ?? source.replace(/\.strings$/, ".stringsdict");
const target = join(root, "src", "generated", "strings.ts");

// Parses the .strings format: "key" = "value"; with C escapes and comments.
export function parseStrings(text) {
  const out = {};
  let i = 0;
  const n = text.length;
  const skip = () => {
    for (;;) {
      while (i < n && /\s/.test(text[i])) i++;
      if (text.startsWith("//", i)) {
        while (i < n && text[i] !== "\n") i++;
      } else if (text.startsWith("/*", i)) {
        const end = text.indexOf("*/", i + 2);
        if (end < 0) throw new Error("unterminated comment");
        i = end + 2;
      } else return;
    }
  };
  const str = () => {
    if (text[i] !== '"') throw new Error(`expected a string at ${i}`);
    i++;
    let s = "";
    while (i < n && text[i] !== '"') {
      if (text[i] === "\\") {
        const c = text[i + 1];
        i += 2;
        if (c === "n") s += "\n";
        else if (c === "t") s += "\t";
        else if (c === "r") s += "\r";
        else if (c === "U" || c === "u") {
          s += String.fromCharCode(parseInt(text.slice(i, i + 4), 16));
          i += 4;
        } else s += c;
      } else s += text[i++];
    }
    if (text[i] !== '"') throw new Error("unterminated string");
    i++;
    return s;
  };
  for (;;) {
    skip();
    if (i >= n) break;
    const key = str();
    skip();
    if (text[i] !== "=") throw new Error(`expected = after "${key}"`);
    i++;
    skip();
    const value = str();
    skip();
    if (text[i] !== ";") throw new Error(`expected ; after "${key}"`);
    i++;
    if (key in out) throw new Error(`duplicate key "${key}"`);
    out[key] = value;
  }
  return out;
}

// Parses the plural rules of a .stringsdict (an XML property list): each key
// becomes its plural forms ("one", "other", ...) with the count as %d.
export function parseStringsdict(xml) {
  const unescape = (s) => s.replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, "&");
  const tokens = [...xml.matchAll(/<(\/?)(dict|key|string)>([^<]*)/g)];
  let i = 0;
  const value = () => {
    const [, close, tag, text] = tokens[i++];
    if (close) throw new Error("plist: unexpected close");
    if (tag === "string") {
      i++; // </string>
      return unescape(text);
    }
    if (tag !== "dict") throw new Error(`plist: unexpected <${tag}>`);
    const out = {};
    for (;;) {
      const [, c, t, k] = tokens[i];
      if (c && t === "dict") {
        i++;
        return out;
      }
      if (t !== "key") throw new Error("plist: expected a key");
      i += 2; // <key>, </key>
      out[unescape(k)] = value();
    }
  };
  while (i < tokens.length && tokens[i][2] !== "dict") i++;
  const root = value();
  const out = {};
  for (const [key, entry] of Object.entries(root)) {
    const format = entry.NSStringLocalizedFormatKey;
    const m = /^(.*)%(?:\d+\$)?#@(\w+)@(.*)$/s.exec(format);
    if (!m) throw new Error(`plurals: ${key} has no variable`);
    const rule = entry[m[2]];
    const forms = {};
    for (const [form, text] of Object.entries(rule)) {
      if (form.startsWith("NSString")) continue;
      forms[form] = (m[1] + text + m[3]).replace(/%(\d+\$)?l{0,2}d/g, (_, pos) => `%${pos ?? ""}d`);
    }
    out[key] = forms;
  }
  return out;
}

function render(table, plural) {
  const lines = Object.keys(table).sort().map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(table[k])},`);
  const plines = Object.keys(plural).sort().map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(plural[k])},`);
  return [
    "// Generated by scripts/strings.mjs from NotTennaPod-iOS's Localizable.strings and",
    "// Localizable.stringsdict (Android AntennaPod 3.12.1's English strings). Do not edit.",
    "export const strings = {",
    ...lines,
    "} as const;",
    "",
    "export type StringKey = keyof typeof strings;",
    "",
    "export const plurals: Record<PluralKey, Partial<Record<\"zero\" | \"one\" | \"two\" | \"few\" | \"many\" | \"other\", string>>> = {",
    ...plines,
    "};",
    "",
    `export type PluralKey = ${Object.keys(plural).sort().map((k) => JSON.stringify(k)).join(" | ") || "never"};`,
    "",
  ].join("\n");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const check = process.argv.includes("--check");
  if (!existsSync(source)) {
    if (check) {
      console.log(`strings: ${source} not found; keeping the committed table`);
      process.exit(0);
    }
    console.error(`strings: ${source} not found (set NTP_IOS_STRINGS)`);
    process.exit(1);
  }
  const table = parseStrings(readFileSync(source, "utf8"));
  const plural = existsSync(plurals) ? parseStringsdict(readFileSync(plurals, "utf8")) : {};
  const out = render(table, plural);
  if (check) {
    const current = existsSync(target) ? readFileSync(target, "utf8") : "";
    if (current !== out) {
      console.error("strings: src/generated/strings.ts is out of date; run npm run strings");
      process.exit(1);
    }
  } else {
    writeFileSync(target, out);
    console.log(`strings: ${Object.keys(table).length} strings, ${Object.keys(plural).length} plurals`);
  }
}
